"""Same native memory study on X/Y; bounded private result receipt."""
import argparse,base64,gzip,hashlib,importlib.util,io,json,os,pathlib,platform,shutil,signal,subprocess,sys,tarfile,time,zipfile
P=pathlib.Path
PAYLOAD={'base64': '', 'bytes': 56168, 'sha256': '7da7544690faf17fe239b0405103a1e54c68bc3c9505cc5cdcb403575acca677'}
def sha(b):return hashlib.sha256(b).hexdigest()
def save(p,obj):
 raw=(json.dumps(obj,indent=2)+'\n').encode();temp=p.with_name(p.name+'.next');temp.write_bytes(raw);os.replace(temp,p)
def main():
 parser=argparse.ArgumentParser();parser.add_argument('machine',choices=['X','Y']);args=parser.parse_args();machine=args.machine
 root=P('/home/jwk')/('xy-memory-study-20261117-'+machine+'-046');result={'experiment':'XY_MEMORY046','machine':machine,'success':False,'stage':'preflight','frequencyChanged':False,'aenvChanged':False};created=False;child=None
 try:
  assert os.getuid()==os.geteuid()==0 and sys.version_info>=(3,11);os.umask(0o077)
  assert platform.machine()==('aarch64' if machine=='X' else 'x86_64') and platform.node()==('debian188' if machine=='X' else 'debian')
  assert not root.exists() and root.parent.resolve()==root.parent;root.mkdir(mode=0o700);created=True
  deadline=time.monotonic()+9000;data=base64.b64decode(PAYLOAD['base64'],validate=True);assert len(data)==PAYLOAD['bytes'] and sha(data)==PAYLOAD['sha256'];result['payloadSha256']=sha(data)
  with zipfile.ZipFile(io.BytesIO(data)) as z:
   for info in z.infolist():
    parts=pathlib.PurePosixPath(info.filename).parts;assert parts and not info.filename.startswith('/') and all(s not in ('..','') for s in parts) and '\\' not in info.filename and ':' not in info.filename
    target=root.joinpath(*parts);target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(z.read(info));target.chmod(0o600)
  spec=importlib.util.spec_from_file_location('study',root/'memory_study.py');study=importlib.util.module_from_spec(spec);spec.loader.exec_module(study);inventory=study.inventory();save(root/'inventory-root.json',inventory)
  result.update(arch=inventory['machine_arch'],kernel=inventory['kernel'],configuredMtS=inventory['configured_mt_s'],configuredMtSSource=inventory['configured_mt_s_source'])
  assert inventory['page_bytes']==4096 and len(inventory['nodes'][0]['physical_cpu_choices'])>=16
  for name in ('python3','make','cc','perl'):assert shutil.which(name),'Missing prerequisite: '+name
  cgroup=P('/proc/self/cgroup').read_text();result['executionContext']={'cgroup':cgroup,'nice':os.getpriority(os.PRIO_PROCESS,0),'scheduler':os.sched_getscheduler(0)}
  unified=next((x.split(':',2)[2] for x in cgroup.splitlines() if x.startswith('0::')),None)
  if unified is not None:
   group=P('/sys/fs/cgroup')/unified.lstrip('/');assert group.resolve().is_relative_to(P('/sys/fs/cgroup').resolve());quota=(group/'cpu.max').read_text().split();result['executionContext']['cpuMax']=quota
   assert quota[0]=='max' or int(quota[0])/int(quota[1])>=16,'CPU quota below16-core budget'
  env={'PATH':str(root/'private-bin')+':/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','HOME':'/root','LANG':'C.UTF-8','LC_ALL':'C.UTF-8'}
  def run(argv,tag,seconds):
   nonlocal child
   result['stage']=tag;save(root/'progress.json',result)
   with (root/(tag+'.stdout.log')).open('xb') as out,(root/(tag+'.stderr.log')).open('xb') as err:
    child=subprocess.Popen(argv,env=env,stdin=subprocess.DEVNULL,stdout=out,stderr=err,start_new_session=True)
    remaining=deadline-time.monotonic();assert remaining>30,'Global study deadline'
    try:code=child.wait(timeout=min(seconds,remaining))
    except BaseException:
     os.killpg(child.pid,signal.SIGINT)
     try:child.wait(timeout=30)
     except subprocess.TimeoutExpired:os.killpg(child.pid,signal.SIGKILL);child.wait(timeout=10)
     raise
    child=None
   assert code==0,tag+' failed; see retained logs'
  (root/'private-bin').mkdir()
  run(['cc','-O2','-Wall','-Wextra',str(root/'numa_exec.c'),'-o',str(root/'private-bin/numactl')],'build_private_binding',60)
  result['bindingImplementation']='private sched_setaffinity + MPOL_BIND with syscall readback, same source on both hosts'
  cpus=','.join(map(str,inventory['nodes'][0]['physical_cpu_choices'][:16]))
  run([str(root/'private-bin/numactl'),'--physcpubind='+cpus,'--membind=0','/usr/bin/python3','-I','-B','-c','import os; assert len(os.sched_getaffinity(0))==16; print("AFFINITY_READBACK_OK")'],'binding_smoke',30)
  result['stage']='native_build';run(['/usr/bin/python3','-I','-B',str(root/'memory_study.py'),'build'],'native_build',300)
  result['build']=json.loads((root/'build'/platform.machine()/'build.json').read_text());study_dir=root/'ram-local'
  run(['/usr/bin/python3','-I','-B',str(root/'memory_study.py'),'run','--machine',machine,'--cpu-node','0','--memory-nodes','0','--cores','16','--repetitions','5','--samples','5','--output',str(study_dir)],'ram_local_95_cases',7200)
  result['ramComplete']=json.loads((study_dir/'complete.json').read_text());manifest=json.loads((study_dir/'manifest.json').read_text());result['selectedPhysicalCpus']=manifest['selected_physical_cpus'];result['cases']=len(manifest['matrix']);assert result['cases']==95
  cpus=','.join(map(str,manifest['selected_physical_cpus']));result['pageCases']=[]
  for workers in (1,8,32,100):
   folder=root/('page-w%03d'%workers);run(['numactl','--physcpubind='+cpus,'--membind=0','/usr/bin/python3','-I','-B',str(root/'page_path_probe.py'),'--size-mib','1024','--workers',str(workers),'--pairs','3','--output',str(folder)],'page_w%03d'%workers,1500)
   page=json.loads((folder/'result.json').read_text());result['pageCases'].append({'workers':workers,'executionSuccess':page['executionSuccess'],'validComparison':page['validComparison'],'fileRemoved':page['experimentalFileRemoved']});assert page['executionSuccess'] and page['validComparison'] and page['experimentalFileRemoved']
  result['stage']='complete';result['success']=True
 except BaseException as error:result['error']=type(error).__name__+': '+str(error)[:1400]
 finally:
  if child is not None and child.poll() is None:
   try:os.killpg(child.pid,signal.SIGINT);child.wait(timeout=30)
   except BaseException:
    try:os.killpg(child.pid,signal.SIGKILL)
    except ProcessLookupError:pass
  if created:
   result['root']=str(root);save(root/'result.json',result);save(root/'progress.json',result)
   archive=root/'results.tar.gz'
   with tarfile.open(archive,'w:gz',compresslevel=9) as tar:
    for p in root.rglob('*'):
     if not p.is_file() or p.is_symlink() or p==archive or 'build' in p.relative_to(root).parts or 'vendor' in p.relative_to(root).parts:continue
     if p.suffix not in ('.json','.csv','.log','.txt'):continue
     tar.add(p,arcname=p.relative_to(root).as_posix(),recursive=False)
   data=archive.read_bytes();result['archiveBytes']=len(data);result['archiveSha256']=sha(data);result['archivePath']=str(archive)
   if len(data)<=450000:result['archiveBase64']=base64.b64encode(data).decode()
   else:result['archiveRetainedOnly']=True
  raw=json.dumps(result,separators=(',',':'));assert len(raw.encode())<800000;print(raw,flush=True)
if __name__=='__main__':main()
